// Generated by HostingStore and persistentCredentials in packages/hosting,
// using the fixed 00…1f test key and fabricated API, OAuth and managed MCP values.
var legacyFixtures = []struct{ id, kind, plaintext, blob string }{
	{"sample-api", "api_key", `{"type":"api_key","key":"fixture-api-key","env":{"ACCOUNT":"fixture-account"}}`,
		"A04AF6C095CE2EB3619E56EB6718DD6F5394DC68597B5749C8936CFF01566032628F74D5A8F92D4C8580469EFEAFB54802AFDF3AB1B50287E8C0C04C1C9F219E2B2E2BF283D49EDD6AC69F6899F4CD81B1518D465A95213994460C98193B60836E7909DECD7C6ACCF8AC"},
	{"sample-oauth", "oauth", `{"type":"oauth","refresh":"fixture-refresh","access":"fixture-access","expires":2147483647123,"accountId":"fixture-account"}`,
		""},
	{"persona-mcp:sample:test-id", "api_key", `{"type":"api_key","key":"{\"config\":{\"url\":\"https://example.test\"},\"oauth\":{\"access_token\":\"fixture-mcp-token\"}}"}`,
		""},
}

func seedLegacyCredentials(t *testing.T, dir string) {
	t.Helper()
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}
	if err := os.WriteFile(filepath.Join(dir, credentialKey), key, 0600); err != nil {
		t.Fatal(err)
	}
	db, err := openSQLite(filepath.Join(dir, credentialDatabase), "rwc")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = db.Close() }()
	if _, err := db.ExecContext(t.Context(), `
		CREATE TABLE credentials (provider TEXT PRIMARY KEY, type TEXT NOT NULL, value BLOB NOT NULL);
		CREATE TABLE devices (id TEXT PRIMARY KEY);
		INSERT INTO devices VALUES ('existing-device');
	`); err != nil {
		t.Fatal(err)
	}
	for _, f := range legacyFixtures {
		raw, err := hex.DecodeString(f.blob)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := db.ExecContext(t.Context(), "INSERT INTO credentials VALUES (?,?,?)", f.id, f.kind, raw); err != nil {
			t.Fatal(err)
		}
	}
}

func TestLegacyCredentialRoundTrip(t *testing.T) {
	dir := t.TempDir()
	seedLegacyCredentials(t, dir)
	store, err := OpenCredentials(t.Context(), dir)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = store.Close() }()
	for _, f := range legacyFixtures {
		ref := Ref{Scope: "provider", Name: f.id}
		if strings.HasPrefix(f.id, "persona-mcp:") {
			ref.Scope = "mcp"
		}
		value, err := store.Get(t.Context(), ref)
		if err != nil || string(value.Secret) != f.plaintext || value.Metadata["type"] != f.kind {
			t.Fatalf("reading legacy %s: %v", f.id, err)
		}
		if f.kind == "oauth" && value.ExpiresAt.UnixMilli() != 2147483647123 {
			t.Fatal("legacy OAuth expiry was lost")
		}
		if err := store.Put(t.Context(), value); err != nil {
			t.Fatal(err)
		}
		reopened, err := store.Get(t.Context(), ref)
		if err != nil || string(reopened.Secret) != f.plaintext || reopened.UpdatedAt.IsZero() {
			t.Fatalf("round-tripping legacy %s: %v", f.id, err)
		}
		var ciphertext []byte
		if err := store.db.QueryRowContext(t.Context(), "SELECT value FROM credentials WHERE provider=?", f.id).
			Scan(&ciphertext); err != nil {
			t.Fatal(err)
		}
		if bytes.Contains(ciphertext, []byte("fixture-")) || bytes.EqualFold([]byte(hex.EncodeToString(ciphertext)), []byte(f.blob)) {
			t.Fatal("credential was not re-encrypted with a fresh nonce")
		}
	}
	var device string
	if err := store.db.QueryRowContext(t.Context(), "SELECT id FROM devices").Scan(&device); err != nil || device != "existing-device" {
		t.Fatalf("existing devices must be left intact: %v", err)
	}
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}
	t.Run("TypeScript reads Go writes", func(t *testing.T) {
		verifyLegacyWithNode(t, dir)
	})
}

func verifyLegacyWithNode(t *testing.T, dir string) {
	t.Helper()
	node, err := exec.LookPath("node")
	if err != nil {
		t.Skip("Node is not installed")
	}
	version, err := exec.CommandContext(t.Context(), node, "-p", "process.versions.node.split('.')[0]").Output()
	if err != nil {
		t.Fatal(err)
	}
	major, _ := strconv.Atoi(strings.TrimSpace(string(version)))
	if major < 24 {
		t.Skip("Node 24+ is required for the TypeScript hosting modules")
	}
	cmd := exec.CommandContext(t.Context(), node, "--no-warnings", "--input-type=module", "-e", `
		import assert from "node:assert/strict";
		import { HostingStore } from "../../packages/hosting/src/store.ts";
		import { persistentCredentials } from "../../packages/hosting/src/credentials.ts";
		const store = await HostingStore.open(process.argv[1]);
		try {
			const credentials = persistentCredentials(store);
			for (let i = 2; i < process.argv.length; i += 2) {
				assert.deepEqual(await credentials.read(process.argv[i]), JSON.parse(process.argv[i+1]));
			}
		} finally { await store.close(); }
	`, dir, legacyFixtures[0].id, legacyFixtures[0].plaintext, legacyFixtures[1].id, legacyFixtures[1].plaintext,
		legacyFixtures[2].id, legacyFixtures[2].plaintext)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("TypeScript compatibility check failed: %v\n%s", err, out)
	}
}

func TestListShowsLegacyOAuthExpiryWithoutSecrets(t *testing.T) {
	dir := t.TempDir()
	seedLegacyCredentials(t, dir)
	ctx := t.Context()
	store, err := OpenCredentials(ctx, dir)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = store.Close() }()
	ref := Ref{Scope: "provider", Name: "sample-oauth"}
	wantExpiry := func(millis int64, goMetadata bool) {
		t.Helper()
		list, err := store.List(ctx, ref.Scope, "")
		if err != nil {
			t.Fatal(err)
		}
		for _, c := range list {
			if c.Ref == ref {
				if c.Secret != nil || c.ExpiresAt.UnixMilli() != millis || (c.Metadata["source"] == "go") != goMetadata {
					t.Fatalf("bad OAuth listing: expiry=%v, metadata=%v", c.ExpiresAt, c.Metadata)
				}
				return
			}
		}
		t.Fatal("missing OAuth credential in list")
	}
	wantExpiry(2147483647123, false)
	value, err := store.Get(ctx, ref)
	if err != nil {
		t.Fatal(err)
	}
	value.Metadata["source"] = "go"
	if err := store.Put(ctx, value); err != nil {
		t.Fatal(err)
	}
	wantExpiry(2147483647123, true)

	// TypeScript refreshes the rows without updating the Go side table.
	refreshed := sealCredential(store.aead, []byte(`{"type":"oauth","expires":2147483647999}`), ref.Name)
	if _, err := store.db.ExecContext(ctx, "UPDATE credentials SET value=? WHERE provider=?", refreshed, ref.Name); err != nil {
		t.Fatal(err)
	}
	wantExpiry(2147483647999, false)
}

func TestCredentialStoreCRUD(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "data # special")
	store, err := OpenCredentials(t.Context(), dir)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = store.Close() }()
	ref := Ref{Scope: "service", Owner: "bot", Name: "token"}
	expiry := time.Unix(2147483647, 0).UTC()
	c := Credential{Ref: ref, Secret: []byte{0, 1, 42, 255}, Metadata: map[string]string{"label": "example"}, ExpiresAt: expiry}
	if err := store.Put(t.Context(), c); err != nil {
		t.Fatal(err)
	}
	items, err := store.List(t.Context(), "service", "bot")
	if err != nil || len(items) != 1 || items[0].Secret != nil || !items[0].ExpiresAt.Equal(expiry) ||
		items[0].Metadata["label"] != "example" || items[0].UpdatedAt.IsZero() {
		t.Fatalf("bad credential metadata: %v, %v", items, err)
	}
	value, err := store.Get(t.Context(), ref)
	if err != nil || !bytes.Equal(value.Secret, c.Secret) {
		t.Fatalf("bad credential: %v", err)
	}
	if _, err := store.db.ExecContext(t.Context(), "UPDATE persona_credentials SET name='different'"); err != nil {
		t.Fatal(err)
	}
	wrong := Ref{Scope: ref.Scope, Owner: ref.Owner, Name: "different"}
	if _, err := store.Get(t.Context(), wrong); err == nil || errors.Is(err, ErrNotFound) {
		t.Fatalf("moving a credential to another identity must fail authentication: %v", err)
	}
	if err := store.Delete(t.Context(), wrong); err != nil {
		t.Fatal(err)
	}
	if _, err := store.Get(t.Context(), wrong); !errors.Is(err, ErrNotFound) {
		t.Fatalf("deleted credential: %v", err)
	}
}

func TestCredentialStoreNeverReplacesExistingKey(t *testing.T) {
	dir := t.TempDir()
	seedLegacyCredentials(t, dir)
	key := filepath.Join(dir, credentialKey)
	if err := os.Remove(key); err != nil {
		t.Fatal(err)
	}
	if _, err := OpenCredentials(t.Context(), dir); err == nil {
		t.Fatal("missing key should not be regenerated over an existing database")
	}
	if _, err := os.Stat(key); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("missing key was replaced: %v", err)
	}
	if err := os.WriteFile(key, []byte("invalid"), 0600); err != nil {
		t.Fatal(err)
	}
	if _, err := OpenCredentials(t.Context(), dir); err == nil {
		t.Fatal("invalid key should be refused")
	}
	if raw, err := os.ReadFile(key); err != nil || string(raw) != "invalid" {
		t.Fatalf("invalid key was replaced: %v", err)
	}
}
